// The C++ encoders against test/golden/wire_vectors.txt, the byte vectors
// the Python and Rust tests check too (python/tests/test_golden.py,
// rust/tests/golden.rs). The file is generated by test/golden/generate.py
// with no Song runtime, so it is an independent statement of the format.

#include <gtest/gtest.h>
#include "song/buffer.hpp"
#include "song/wire.hpp"
#include "song/security.hpp"

#include <bit>
#include <fstream>
#include <functional>
#include <map>
#include <string>
#include <vector>

using namespace song;

namespace {

std::string to_hex(const Buffer& buf) {
    static const char* digits = "0123456789abcdef";
    std::string out;
    for (std::byte b : buf.view()) {
        auto value = static_cast<unsigned>(b);
        out += digits[value >> 4];
        out += digits[value & 0xF];
    }
    return out;
}

std::vector<std::byte> from_hex(const std::string& hex) {
    std::vector<std::byte> out;
    for (size_t ndx = 0; ndx + 1 < hex.size(); ndx += 2) {
        out.push_back(static_cast<std::byte>(std::stoi(hex.substr(ndx, 2), nullptr, 16)));
    }
    return out;
}

std::string trim(const std::string& s) {
    size_t first = s.find_first_not_of(" \t\r\n");
    if (first == std::string::npos) {
        return "";
    }
    size_t last = s.find_last_not_of(" \t\r\n");
    return s.substr(first, last - first + 1);
}

// name -> hex, from the golden file.
std::map<std::string, std::string> load_vectors() {
    std::map<std::string, std::string> out;
    std::ifstream in(std::string(SONG_SOURCE_DIR) + "/test/golden/wire_vectors.txt");
    std::string line;
    while (std::getline(in, line)) {
        line = trim(line);
        if (line.empty() || line[0] == '#') {
            continue;
        }
        size_t eq = line.find('=');
        if (eq == std::string::npos) {
            continue;
        }
        out[trim(line.substr(0, eq))] = trim(line.substr(eq + 1));
    }
    return out;
}

Buffer i32_args(std::initializer_list<i32> values) {
    Buffer buf;
    for (i32 v : values) {
        encode_i32(buf, v);
    }
    return buf;
}

// What SecureTransport puts on the wire for msg: payload_size grown by the
// tag size, the payload, then the tag over the untagged message.
Buffer tagged(const Buffer& msg, const std::string& key) {
    HmacTag tag = compute_hmac(key, msg);
    Buffer out;
    out.write(msg.data(), msg.size());
    u32 size = 0;
    std::memcpy(&size, out.data() + 8, sizeof(u32));
    size += static_cast<u32>(kHmacTagSize);
    std::memcpy(out.data() + 8, &size, sizeof(u32));
    out.write(tag.data(), kHmacTagSize);
    return out;
}

// Every vector the C++ runtime builds, by name.
std::map<std::string, std::function<Buffer()>> builders(const std::string& hmac_key) {
    std::map<std::string, std::function<Buffer()>> m;
    m["bool_true"] = [] { Buffer b; encode_bool(b, true); return b; };
    m["bool_false"] = [] { Buffer b; encode_bool(b, false); return b; };
    m["i8_minus_2"] = [] { Buffer b; encode_i8(b, -2); return b; };
    m["i16_minus_2"] = [] { Buffer b; encode_i16(b, -2); return b; };
    m["i32_0x12345678"] = [] { Buffer b; encode_i32(b, 0x12345678); return b; };
    m["i64_minus_2"] = [] { Buffer b; encode_i64(b, -2); return b; };
    m["u8_0xab"] = [] { Buffer b; encode_u8(b, 0xAB); return b; };
    m["u16_0xbeef"] = [] { Buffer b; encode_u16(b, 0xBEEF); return b; };
    m["u32_0xdeadbeef"] = [] { Buffer b; encode_u32(b, 0xDEADBEEF); return b; };
    m["u64_0x0102030405060708"] = [] { Buffer b; encode_u64(b, 0x0102030405060708ULL); return b; };
    m["f32_1_5"] = [] { Buffer b; encode_f32(b, 1.5f); return b; };
    m["f64_minus_2_25"] = [] { Buffer b; encode_f64(b, -2.25); return b; };
    m["string_hello"] = [] { Buffer b; encode_string(b, "hello, song"); return b; };
    m["string_empty"] = [] { Buffer b; encode_string(b, ""); return b; };
    m["string_utf8"] = [] { Buffer b; encode_string(b, "h\xC3\xA9llo \xE2\x99\xAB"); return b; };
    m["bytes_00_ff_10"] = [] {
        Buffer b;
        std::vector<std::byte> raw{std::byte{0x00}, std::byte{0xFF}, std::byte{0x10}};
        encode_bytes(b, raw);
        return b;
    };
    m["array_i32"] = [] {
        Buffer b;
        std::vector<i32> v{1, -1, 65536};
        encode_array<i32>(b, v);
        return b;
    };
    m["array_string"] = [] {
        Buffer b;
        std::vector<std::string> v{"a", "bc"};
        encode_array<std::string>(b, v);
        return b;
    };
    m["array_nested_i32"] = [] {
        Buffer b;
        std::vector<std::vector<i32>> v{{1, 2}, {}, {3}};
        encode_array<std::vector<i32>>(b, v);
        return b;
    };
    // An optional is a bool, then the value when true.
    m["optional_i32_some_7"] = [] {
        Buffer b;
        encode_optional(b, std::optional<i32>(7), [&](const auto& v) { encode_i32(b, v); });
        return b;
    };
    m["optional_none"] = [] {
        Buffer b;
        encode_optional(b, std::optional<i32>(), [&](const auto& v) { encode_i32(b, v); });
        return b;
    };
    m["header_call_seq7_size4"] = [] {
        Buffer b;
        wire::encode_header(b, wire::Header{wire::kMagic, wire::MsgFlags::none, wire::MsgType::call, 0, 4, 7});
        return b;
    };
    m["msg_init"] = [] {
        std::vector<wire::MethodDescriptor> methods{
            {1, 1, wire::MethodFlags::none, 0},
            {2, 3, wire::MethodFlags::streaming, 0},
        };
        u32 caps = static_cast<u32>(wire::Capability::streaming) | static_cast<u32>(wire::Capability::hmac);
        return wire::create_init_message(wire::kFirstVersion, wire::kCurrentVersion, caps, methods);
    };
    m["msg_init_ack"] = [] {
        return wire::create_init_ack_message(wire::kFirstVersion, wire::kCurrentVersion,
                                             static_cast<u32>(wire::Capability::hmac));
    };
    m["msg_call"] = [] { return wire::create_call_message(7, 1, 2, i32_args({5, 9})); };
    m["msg_result"] = [] { return wire::create_result_message(7, i32_args({14})); };
    m["msg_error"] = [] { return wire::create_error_message(7, ErrorCode::unknown_method, "boom"); };
    m["msg_stream"] = [] { return wire::create_stream_message(9, i32_args({1})); };
    m["msg_stream_end"] = [] { return wire::create_stream_end_message(9); };
    m["msg_shutdown"] = [] { return wire::create_shutdown_message(); };
    m["hmac_key"] = [hmac_key] {
        Buffer b;
        b.write(hmac_key.data(), hmac_key.size());
        return b;
    };
    m["msg_call_tagged"] = [hmac_key] { return tagged(wire::create_call_message(7, 1, 2, i32_args({5, 9})), hmac_key); };
    m["msg_stream_end_tagged"] = [hmac_key] { return tagged(wire::create_stream_end_message(9), hmac_key); };
    return m;
}

} // namespace

TEST(GoldenVectorTest, EncodersMatchTheSharedVectors) {
    if (std::endian::native != std::endian::little) {
        GTEST_SKIP() << "the golden vectors are little-endian and the runtime writes native byte order";
    }
    auto vectors = load_vectors();
    ASSERT_FALSE(vectors.empty()) << "test/golden/wire_vectors.txt not found or empty";
    ASSERT_TRUE(vectors.count("hmac_key"));

    auto key_bytes = from_hex(vectors["hmac_key"]);
    std::string key(reinterpret_cast<const char*>(key_bytes.data()), key_bytes.size());
    auto build = builders(key);

    // Every vector in the file has a C++ builder, and every builder a vector:
    // a vector added for one language is checked in this one too.
    for (const auto& [name, hex] : vectors) {
        auto it = build.find(name);
        ASSERT_NE(it, build.end()) << "no C++ builder for golden vector " << name;
        EXPECT_EQ(to_hex(it->second()), hex) << "golden vector " << name;
    }
    for (const auto& [name, fn] : build) {
        EXPECT_TRUE(vectors.count(name)) << name << " is not in the golden vector file";
    }
}

TEST(GoldenVectorTest, DecodersReadTheSharedVectors) {
    if (std::endian::native != std::endian::little) {
        GTEST_SKIP() << "the golden vectors are little-endian and the runtime writes native byte order";
    }
    auto vectors = load_vectors();
    ASSERT_FALSE(vectors.empty());
    auto load = [&](const std::string& name) {
        Buffer b;
        auto raw = from_hex(vectors[name]);
        b.write(raw.data(), raw.size());
        return b;
    };

    Buffer s = load("string_utf8");
    EXPECT_EQ(decode_string(s), "h\xC3\xA9llo \xE2\x99\xAB");
    Buffer nested = load("array_nested_i32");
    auto arr = decode_array<std::vector<i32>>(nested);
    ASSERT_EQ(arr.size(), 3u);
    EXPECT_EQ(arr[0], (std::vector<i32>{1, 2}));
    EXPECT_TRUE(arr[1].empty());
    EXPECT_EQ(arr[2], (std::vector<i32>{3}));

    Buffer init = load("msg_init");
    auto hdr = wire::decode_header_validated(init);
    EXPECT_EQ(hdr.type, wire::MsgType::init);
    auto msg = wire::decode_init(init);
    EXPECT_EQ(msg.current_version, wire::kCurrentVersion);
    EXPECT_EQ(msg.capabilities, 0x41u);
    ASSERT_EQ(msg.method_count, 2u);
    wire::decode_method_descriptor(init);
    auto second = wire::decode_method_descriptor(init);
    EXPECT_EQ(second.service_id, 2);
    EXPECT_EQ(second.method_id, 3);
    EXPECT_EQ(second.flags, wire::MethodFlags::streaming);

    // The tagged call verifies with the key and not with another.
    Buffer call = load("msg_call");
    Buffer tagged_call = load("msg_call_tagged");
    auto key_bytes = from_hex(vectors["hmac_key"]);
    std::string key(reinterpret_cast<const char*>(key_bytes.data()), key_bytes.size());
    HmacTag tag{};
    std::memcpy(tag.data(), tagged_call.data() + tagged_call.size() - kHmacTagSize, kHmacTagSize);
    EXPECT_TRUE(verify_hmac(key, call, tag));
    EXPECT_FALSE(verify_hmac(key + "x", call, tag));
}

TEST(GoldenVectorTest, OptionalRoundTrips) {
    Buffer b;
    encode_optional(b, std::optional<std::string>("hi"), [&](const auto& v) { encode_string(b, v); });
    encode_optional(b, std::optional<i64>(), [&](const auto& v) { encode_i64(b, v); });
    encode_optional(b, std::optional<i64>(-9), [&](const auto& v) { encode_i64(b, v); });
    b.reset_read();
    EXPECT_EQ(decode_optional<std::string>(b, [&]() { return decode_string(b); }), std::optional<std::string>("hi"));
    EXPECT_EQ(decode_optional<i64>(b, [&]() { return decode_i64(b); }), std::nullopt);
    EXPECT_EQ(decode_optional<i64>(b, [&]() { return decode_i64(b); }), std::optional<i64>(-9));
    EXPECT_EQ(b.remaining(), 0u);

    // A present optional with its value cut off is an error, not a default.
    Buffer cut;
    encode_bool(cut, true);
    cut.reset_read();
    EXPECT_THROW(decode_optional<i32>(cut, [&]() { return decode_i32(cut); }), std::exception);
}
